const STORE='shogunate-sim-save-v1', SETTINGS='shogunate-sim-settings-v1', DB_NAME='shogunate-sim-db-v1', DB_STORE='saves';
let storageWriteQueue=Promise.resolve(), indexedDbReady=false, idbSaveCache=null, storageGeneration=0;
function openSaveDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB 不可用'));return}const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(DB_STORE))db.createObjectStore(DB_STORE)};req.onsuccess=()=>{indexedDbReady=true;resolve(req.result)};req.onerror=()=>reject(req.error||new Error('无法打开本地数据库'))})}
async function idbPutSave(value){const db=await openSaveDB();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(value,'current');tx.oncomplete=()=>{db.close();resolve(true)};tx.onerror=()=>{const e=tx.error;db.close();reject(e||new Error('IndexedDB 写入失败'))};tx.onabort=()=>{db.close();reject(tx.error||new Error('IndexedDB 写入中断'))}})}
async function idbGetSave(){const db=await openSaveDB();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly'),req=tx.objectStore(DB_STORE).get('current');req.onsuccess=()=>{const v=req.result||null;db.close();resolve(v)};req.onerror=()=>{const e=req.error;db.close();reject(e||new Error('IndexedDB 读取失败'))}})}
function compactSaveForLocalStorage(copy){const x=safeClone(copy);x.customBackgrounds=(x.customBackgrounds||[]).slice(-2);for(const groups of [x.people?.government?.swords||[],x.people?.government?.saniwa||[],x.people?.government?.staff||[],x.people?.government?.shikigami||[],x.people?.present?.friends||[]])for(const person of groups){if(person.avatarData&&person.avatarData.length>180000)person.avatarData='';if(Array.isArray(person.memory))person.memory=person.memory.slice(-30);if(Array.isArray(person.eventMemories))person.eventMemories=person.eventMemories.slice(-30)}for(const k of ['activity','logs','timeline','snapshots','autonomousInteractions'])if(Array.isArray(x[k]))x[k]=x[k].slice(-80);for(const k of ['government','present'])if(Array.isArray(x.worldMemories?.[k]))x.worldMemories[k]=x.worldMemories[k].slice(-60);return x}
async function readBestSave(){try{const v=await idbGetSave();if(v&&[1,2,3].includes(Number(v.version)))return v}catch(e){}return loadGameLegacy()}
function loadGameLegacy(){try{const x=JSON.parse(localStorage.getItem(STORE)||'null');if(!x||![1,2,3].includes(x.version))return null;return normalizePeopleState(migrateSave(x))}catch{return null}}
function migrateSave(x){if(!x.calendar){const now=new Date();x.calendar={year:2205,month:now.getMonth()+1,date:now.getDate()}}x.version=3;x.lastWallClock=x.lastWallClock||Date.now();if(!x.realDateKey){const n=new Date();x.realDateKey=`${n.getFullYear()}-${n.getMonth()+1}-${n.getDate()}`}return x}
function seasonForMonth(m){return m>=3&&m<=5?'春':m>=6&&m<=8?'夏':m>=9&&m<=11?'秋':'冬'}
function dateLabel(){const c=state?.calendar;if(!c)return '2205年';return `${c.year}年${c.month}月${c.date}日`}
function shiftCalendar(days){if(!state)return;const c=state.calendar||(state.calendar={year:2205,month:4,date:1});const d=new Date(c.year,c.month-1,c.date+days);c.year=d.getFullYear();c.month=d.getMonth()+1;c.date=d.getDate();state.season=seasonForMonth(c.month)}
