function freshPerson(name,type,world='government',extra={}){const profile=type==='swords'?(characterProfile(name)||{}):{};const genericBackground=type==='saniwa'?'其他审神者。经历、所属本丸、行事风格与专长应依据玩家填写的信息和后续剧情逐步补充，不套用刀剑男士的刀种、刀派或锻刀时间字段。':type==='staff'?'时之政府工作人员。部门职责、工作经历与个人特点依据玩家填写的信息和后续剧情逐步补充。':'';const summary=extra.summary||[profile.baseEntry,profile.detailEntry,profile.moegirlSupplement?`【萌娘百科补充资料（需与游戏原文区分）】${profile.moegirlSupplement}`:'',profile.officialSupplement?`【官方角色资料补充】${profile.officialSupplement}`:'',profile.profileDossier?`【结构化人物档案】外貌：${profile.profileDossier.visualDesign||'待补充'}；内番服：${profile.profileDossier.innerWear||'待补充'}；性格/行为线索（须与外貌分开判断）：${profile.profileDossier.personalityEvidence||'待补充'}；线索边界：${profile.profileDossier.personalityEvidenceStatus||'待核验'}；自我介绍依据：${profile.profileDossier.voiceEvidence||'待补充'}；归来台词依据：${profile.profileDossier.returnBehaviorEvidence||'待补充'}；性格线索：${(profile.profileDossier.personalityTags||[]).join('、')}；互动约束：${(profile.profileDossier.guardrails||[]).join('；')}`:'',profile.profileDossier?`【资料可信度与缺项】官方来源：${profile.profileDossier.officialSourceStatus||'待核验'}；二次资料：${profile.profileDossier.secondarySourceStatus||'待核验'}；缺项：${(profile.profileDossier.missingFields||[]).join('、')||'无已登记缺项'}；来源台账：${(profile.profileDossier.sourceLedger||[]).filter(x=>['official_fact','worldbook_voice','secondary_fact'].includes(x.kind)).slice(0,5).map(x=>`${x.label}：${String(x.text||'').slice(0,120)}`).join('；')}`:'',Array.isArray(profile.officialVerifiedFacts)&&profile.officialVerifiedFacts.length?`【官方资料核验要点】${profile.officialVerifiedFacts.join('；')}`:''].filter(Boolean).join('\n')||genericBackground;return {id:uid(),name,type,world,species:extra.species||(type==='swords'?'付丧神':type==='shikigami'?'式神':'人类'),kind:({swords:'刀剑男士',saniwa:'其他审神者',staff:'时之政府工作人员',shikigami:'式神',friends:'现世相识的人'})[type]||'现世相识的人',role:extra.role||'',swordType:type==='swords'?(extra.swordType||profile.swordType||''):'',faction:type==='swords'?(extra.faction||profile.faction||''):'',forgeTime:type==='swords'?(profile.forgeTime||''):'',playerRelation:extra.playerRelation||'',affection:25,affinity:'普通',relation:'未定义',relationshipType:extra.relationshipType||'未定义',relationshipNote:'',status:'正常',location:world==='present'?'现世':'本丸',summary,characterProfile:profile,appearance:extra.appearance||profile.appearance||'',greeting:extra.greeting||profile.greeting||'',memory:[],eventMemories:[],knownFacts:[],mood:'平静',schedule:'日常事务',isCanon:!!extra.isCanon,createdAt:Date.now()};}
function uid(){return Math.random().toString(36).slice(2,9)+Date.now().toString(36).slice(-4)}
function safeClone(x){return JSON.parse(JSON.stringify(x))}
