function worldbookSearchTerms(value,limit=90){const text=String(value||'').toLowerCase();const terms=[];const seen=new Set();const add=t=>{t=String(t||'').trim();if(t.length<2||seen.has(t))return;seen.add(t);terms.push(t)};for(const token of (text.match(/[a-z0-9_-]{2,}|[\u4e00-\u9fff]{2,}/g)||[])){if(/[\u4e00-\u9fff]/.test(token)){if(token.length<=6)add(token);else{for(let n=4;n>=2;n--)for(let i=0;i+n<=token.length;i++)add(token.slice(i,i+n))}}else add(token)}return terms.slice(0,limit)}
async function retrieveWorldbook(query,person){let text=worldbookCache||window.EMBEDDED_WORLDBOOK||'';if(text&&!worldbookCache)worldbookCache=text;try{if(!text){text=await (await fetch('worldbook.txt')).text();worldbookCache=text}}catch{return fallbackWorldRules(person)}const characterSource=person.characterProfile?[person.characterProfile.baseEntry,person.characterProfile.detailEntry].filter(Boolean).join('\n'):'';const recentContext=(person.memory||[]).slice(-6).map(m=>String(m.content||'')).join(' ');const terms=worldbookSearchTerms(person.name+' '+person.swordType+' '+person.role+' '+(person.playerRelation||''),25).concat(worldbookSearchTerms(query,55),worldbookSearchTerms(recentContext+' '+(person.summary||''),25)).filter((x,i,a)=>a.indexOf(x)===i&&!['我们','你们','他们','这个','那个','然后','因为','所以','怎么','什么','可以','现在','之前','之后','今天','刚才','觉得','知道','没有','不是','就是','一个','还有','如果','自己','对方'].includes(x));const paragraphs=text.split(/\n\s*\n/).filter(p=>p.trim());let scored=paragraphs.map(p=>({p,score:terms.reduce((n,t)=>n+(p.toLowerCase().includes(t)?(t===person.name.toLowerCase()?7:t.length>=4?2:1):0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);const retrieved=scored.slice(0,10).map(x=>x.p).join('\n\n')||fallbackWorldRules(person);const worldbookBudget=state?.settings?.chatLength==='short'?7000:state?.settings?.chatLength==='long'?15000:11000;return (`【角色卡原文】\n${characterSource}\n\n【动态检索】\n${retrieved}`).slice(0,worldbookBudget)}
function fallbackWorldRules(person){return `世界书核心规则：\n- 《刀剑乱舞》同人模拟，人物表现遵循原作与随附世界书，不得随意崩坏。\n- 刀剑男士全部为男性；保持各自独立意志、日程与目标。\n- 时之政府体系与现世完全隔离，不共享人物、记忆、关系、消息或事件。\n- 未经玩家明确允许，任何刀剑男士不得通过任何途径得知玩家真名。\n- 时之政府/本丸使用玩家代号；现世按关系称呼，不使用审神者代号。\n- 角色只能知道自己实际接触或合理获知的信息，不得拥有上帝视角。\n- 当前对话角色：${person.name}；分类：${person.kind}；世界：${person.world==='present'?'现世':'时之政府体系'}；已知背景：${person.summary||'无'}。`}
let activeRecallQuery='';
function ensureRelationshipGraph(){if(!state.relationshipGraph)state.relationshipGraph={edges:[]};if(!Array.isArray(state.relationshipGraph.edges))state.relationshipGraph.edges=[];return state.relationshipGraph}
function recordRelationshipEdge(from,to,kind,detail='',source='gameplay'){
 if(!from||!to||from===to)return;const a=findPerson(from),b=findPerson(to);if(!a||!b||a.world!==b.world)return;
 const graph=ensureRelationshipGraph();let edge=graph.edges.find(e=>e.from===from&&e.to===to&&e.kind===kind);if(!edge){edge={from,to,kind,detail:String(detail||''),source,createdDay:state.day,updatedDay:state.day,weight:1};graph.edges.push(edge)}else{edge.detail=String(detail||edge.detail||'');edge.updatedDay=state.day;edge.weight=Math.min(20,Number(edge.weight||1)+1)}
 graph.edges=graph.edges.slice(-500);
}
function retrieveRelevantMemories(p,query='',limit=8){
 if(!p)return[];
 const source=[];
 if(p.memorySummary)source.push({type:'长期摘要',text:String(p.memorySummary),at:0,source:'summary'});
 for(const x of (p.eventMemories||[]))source.push({type:'亲历事件',text:`第${x.day||'?'}日「${x.title||''}」${x.summary||x.result||''}；选择：${x.choice||'未记录'}；结果：${x.result||'未记录'}`,at:Number(x.at)||0,source:'event'});
 for(const x of (p.knownFacts||[]))source.push({type:'已知事实',text:typeof x==='string'?x:String(x?.fact||x?.text||JSON.stringify(x)),at:Number(x?.at)||0,source:'fact'});
 for(const x of (p.memory||[]).slice(-100))source.push({type:x.role==='user'?'玩家说过':'角色回应',text:String(x.content||''),at:Number(x.at)||0,source:'dialogue'});
 const q=String(query||'').toLowerCase();
 const stop=new Set(['我们','你们','他们','这个','那个','然后','因为','所以','怎么','什么','为什么','可以','现在','之前','之后','今天','刚才','一下','觉得','知道','没有','不是','就是','一个','还有','如果','自己','对方','角色','事情','那件','有关','关于','告诉','记得']);
 const terms=new Set(q.split(/[\s，。！？、；：,.!?;:「」『』“”"（）()【】\[\]…]+/).map(x=>x.trim()).filter(x=>x.length>=2&&!stop.has(x)).slice(0,25));
 // Chinese has no spaces between words: add a small set of informative 2–4 character fragments.
 const compact=q.replace(/[\s，。！？、；：,.!?;:「」『』“”"（）()【】\[\]…]/g,'');
 for(let n=4;n>=2;n--){for(let i=0;i<=compact.length-n&&terms.size<45;i++){const t=compact.slice(i,i+n);if(!stop.has(t)&&!/^(.)\1+$/.test(t))terms.add(t)}}
 const topicHints=['约定','承诺','秘密','误会','冲突','礼物','受伤','道歉','信任','关系','真名','调查','证据','任务','告白','生日','承诺','选择','结果','欠下','答应','谎言','担心','帮助','争吵'];
 const queryTopics=topicHints.filter(t=>q.includes(t));
 const scored=source.map((x,i)=>{const text=x.text.toLowerCase();let score=0;const matched=[];for(const term of terms){if(term.length>=2&&q.includes(term)&&text.includes(term)){score+=term.length>=4?3:1;matched.push(term)}}for(const t of queryTopics)if(text.includes(t)){score+=2;matched.push(t)}
  // Recency breaks ties only; it must never make unrelated memories look relevant.
  const recency=Math.min(0.4,Math.max(0,Number(x.at)||0)/1e16);return {...x,score:score+recency,matched:[...new Set(matched)],i}}).filter(x=>x.matched.length>0);
 const max=Math.max(0,Math.min(12,Number(limit)||8));
 if(!scored.length){if(!q.trim())return source.slice(-Math.min(max,3)).map(x=>`${x.type}（按时间回顾）：${x.text.slice(0,260)}`);return source.filter(x=>x.source==='event'||x.source==='summary').slice(-Math.min(max,2)).map(x=>`${x.type}（未找到精确匹配，仅作背景参考）：${x.text.slice(0,220)}`)}
 scored.sort((a,b)=>b.score-a.score||b.i-a.i);return scored.slice(0,max).map(x=>`${x.type}（匹配线索：${x.matched.slice(0,5).join('、')}）：${x.text.slice(0,320)}`)
}
function relationshipGraphContext(p){
 const graph=ensureRelationshipGraph();const edges=graph.edges.filter(e=>e.from===p.id||e.to===p.id);const rows=edges.slice(-20).map(e=>{const other=findPerson(e.from===p.id?e.to:e.from);if(!other||other.world!==p.world)return'';return `${other.name}：${e.kind}${e.detail?`（${e.detail}）`:''}；最近更新第${e.updatedDay||e.createdDay||'?'}日`}).filter(Boolean);
 const knownPeers=(p.type==='swords'?(p.characterProfile||characterProfile(p.name)||{}).relatedCharacters||[]:[]).filter(name=>(p.world==='present'?state.people.present.friends:allGovernmentPeople()).some(x=>x.name===name)).slice(0,12);
 return `【关系图谱（仅记录已建立的边，不等于角色自动知情）】\n${rows.join('\n')||'暂无玩家实际建立的角色关系边'}\n【设定资料中的关联人物】${knownPeers.join('、')||'暂无已登记关联人物'}\n注意：资料上的关联、同处一个世界或共同参与事件不代表亲密、敌对或彼此知道全部隐私。`;
}
function buildRoleplayContinuityContext(p){
 const story=state?.customStory||{};const text=String(story.text||'').trim();
 const all=[...(state?.people?.government?.swords||[]),...(state?.people?.government?.saniwa||[]),...(state?.people?.government?.staff||[]),...(state?.people?.government?.shikigami||[]),...(state?.people?.present?.friends||[]),...(state?.people?.present?.family||[])];
 const mentioned=all.filter(x=>x&&x.name&&text.includes(x.name)).map(x=>x.name);
 const eventMem=(p.eventMemories||[]).slice(-8).map(x=>`第${x.day||'?'}日「${x.title||'未命名事件'}」：玩家选择「${x.choice||'未记录'}」；结果「${x.result||x.summary||'未记录'}」`).join('\n');
 const known=(p.knownFacts||[]).slice(-12).join('\n');
 const relationHistory=(p.relationshipHistory||[]).slice(-8).map(x=>`第${x.day||'?'}日：好感度${x.from}→${x.to}（${x.fromStage}→${x.toStage}），原因：${x.reason||'互动'}`).join('\n');
 const recent=(state?.eventRecords||[]).filter(x=>(x.participants||[]).includes(p.id)).slice(-6).map(x=>`第${x.day}日「${x.title}」：选择「${x.choice}」→ ${x.result}`).join('\n');
 const relevant=retrieveRelevantMemories(p,activeRecallQuery,8).join('\n');const graphContext=relationshipGraphContext(p);
 const thread=state?.flags?.customStoryFollowup;const storyActive=!!text&&state?.world==='government';
 const themes=[];if(/隐瞒|撒谎|欺骗|伪造|篡改|背叛|秘密|瞒着|真相|证据/.test(text))themes.push('信任/隐瞒/证据');if(/失踪|追踪|调查|线索|异常|谜|匿名信/.test(text))themes.push('调查/悬疑');if(/争吵|冲突|误会|嫉妒|背叛|分歧/.test(text))themes.push('关系冲突');if(/受伤|生病|疲惫|照顾|担心|保护/.test(text))themes.push('照顾/风险');if(/任务|部门|政府|公文|审查|违规/.test(text))themes.push('工作/制度');if(/告白|喜欢|恋|约定|礼物|生日/.test(text))themes.push('情感/约定');
 return `【全局角色扮演连续性协议】\n你不是单轮问答机器人，而是持续运行的酒馆角色扮演角色。请在不替玩家行动的前提下，主动呈现角色目标、情绪、顾虑、日常安排和关系变化。不能只重复剧情设定或永远同一种反应；根据角色性格与事实，选择合适的反应方式：回避、追问、坦白一部分、沉默、主动补救、提出条件、误解后修正、拒绝、开玩笑、转移话题、私下调查、寻求帮助、提出新计划等。每次回应至少推进一个可互动细节，但不要每次都强行制造戏剧冲突。\n【自由剧情原文】${storyActive?text.slice(0,5000):'当前不在时之政府剧情场景，不能将政府剧情泄露给现世角色。'}\n【自由剧情可能涉及的人物】${storyActive?(mentioned.join('、')||'未能直接匹配已登记人物；根据文本主题谨慎处理'):'不适用'}\n【剧情主题线索（仅供理解，不是既定事实）】${themes.join('、')||'按原文判断；不得凭空增加阴谋或罪责'}\n【当前连续剧情阶段】${storyActive?(thread?`有待续事件，标题=${thread.title||'自由剧情后续'}；上一选择=${thread.result||thread.choice||'未知'}；计划日=${thread.day}`:`已触发${story.eventsTriggered||0}次；上次选择=${story.lastChoice??'暂无'}`):'无可共享的政府剧情阶段'}\n【该角色已知事实】${known||'暂无单独登记的已知事实'}\n【关系变化历史】${relationHistory||'暂无已记录的阶段变化'}\n【该角色亲历的近期事件】${eventMem||'暂无'}\n【该角色参与的事件账本】${recent||'暂无'}\n${graphContext}\n【按当前话题检索的相关记忆】${relevant||'暂无匹配记忆'}
检索规则：匹配线索只说明文本有关键词重合，不等于该记忆一定与当前事件有关；优先使用亲历事件与明确事实。长期摘要可能压缩了细节，若与原始事件记录冲突，以较具体且较新的原始记录为准。不得把未命中的背景记忆当成当前事实。\n【连续性硬规则】区分客观事实、角色相信的内容、玩家猜测和仍待调查的线索；被提及不等于角色知情，怀疑不等于定罪。角色只根据亲历、告知或合理渠道得知信息。若自由剧情涉及该角色，必须体现其具体立场/知情程度/情绪，但反应必须与剧情内容相符，不要把所有角色都写成心虚，也不要将所有事件都变成调查案。前文已经发生的选择和后果不能无故清零。每轮推进一小步并留下可回应的台阶；需要时可以主动提出问题、行动或新线索。`;
}
function buildSystemPrompt(p,worldbook){const affinityRules=`【初始好感与角色态度】当前角色对玩家的数值好感为${Number(p.affection??25)}/100，阶段为「${p.affinity||affinityLabel(p.affection??25)}」。敌视（0-14）时可以冷硬、戒备、拒绝亲近或质疑玩家；冷淡/普通（15-39）时保持礼貌距离、简短回应，不主动亲昵；信赖（40-69）时愿意合作但仍保留个人边界；亲密（70-89）时语气柔和、会主动关心；深厚羁绊（90-100）时表现出明显信任与亲密。态度须自然符合角色原有人格，不得把敌视角色一律写成温柔，也不得因一次普通对话立刻逆转长期态度。
`;const quoteRules='【聊天文体、篇幅与中文标点硬性规则】这是即时聊天，不是小说正文。优先直接回应玩家刚说的话，像角色本人发消息一样自然交流。通常控制在1—4句；只在有必要时加入一小段动作或神态，不要每次都写环境、心理、背景、镜头或长篇旁白，不要把一句话扩写成数段小说，也不要重复玩家的话。除非玩家明确要求长篇描写、剧情演出或书信，否则对话内容应明显多于描写内容。使用正常、准确的中文标点：句号、逗号、问号、感叹号和引号按语义使用；避免连续堆叠多个感叹号/问号、无意义省略号、破折号和句尾标点混乱。角色的直接对话使用中文双引号“……”；书信、信笺、便条、正式公文等书面文本使用中文直角引号「……」。不要混用两种引号；叙述文字不强行加引号。玩家输入不受此规则约束。发送前逐句检查并修正。';const categoryRules=p.type==='swords'?'你是刀剑男士，物种为付丧神；才使用刀种、刀派、锻刀时间等刀剑相关字段。':p.type==='shikigami'?'你是式神角色。狐之助属于管狐，负责时之政府与本丸之间的工作联络、日课提醒及必要的引导；不使用刀种、刀派、锻刀时间等刀剑字段，也不能充当现世世界的联络渠道。':p.type==='saniwa'?'你是其他审神者：严禁套用刀剑男士模板；不得出现刀种、刀派、锻刀时间等字段。根据已有资料与已发生剧情逐步补充其本丸、审神者经历、专长、性格与工作经历；未知信息不得冒充既定事实。':p.type==='staff'?'你是时之政府工作人员：严禁套用刀剑男士模板；不得出现刀种、刀派、锻刀时间等字段。根据已有资料与剧情补充部门职责、工作经历、专业能力与个人特点；未知信息不得冒充既定事实。':'根据人物自身类别与现有资料展开，不套用刀剑男士字段。';const attendantName=findPerson(state.attendantId)?.name||'尚未指派';const worldBoundary=p.world==='present'?'你正在现世场景中。你只能使用现世人物、现世关系和现世记忆。现世人物严禁与时之政府、政府工作人员、其他审神者、本丸、刀剑男士或式神产生任何关联、猜测、暗示、通信、委托或共同事件；只有玩家在当前对话中主动明确坦白后，才可在该对话范围内回应玩家亲口透露的内容，不能自行扩展成其他渠道或关系。两套世界绝不自动共享人物、关系、消息、事件或记忆。现世称呼不可使用审神者代号。':`你正在时之政府体系内。你只能使用时之政府/本丸人物、该体系关系和记忆。不得调用、提及或暗示现世人物的私人信息；不得让现世人物与本体系自动互通。其他审神者或政府工作人员若需要交接工作，只能联系玩家已指派的近侍「${attendantName}」，且交接范围限于工作事务；不得绕过近侍联系其他刀剑男士。若尚未指派近侍，不得擅自挑选其他刀剑男士代为交接。`;const hasTrueNamePermission=p.type==='swords'&&(state.flags?.trueNameDisclosedTo||[]).includes(p.id);const nameRule=p.type==='swords'?(hasTrueNamePermission?'玩家已明确授权你知晓真名。仅在已授权范围内使用，不得向其他刀剑男士或任何第三人转述，也不得推断额外隐私。':'硬性规则：玩家未明确授权你知晓真名。你不能知道、猜中、推理出或通过任何途径获取玩家真名。不得设计偷听、偷看、转述、梦境、灵力感知、文件泄漏等绕过手段。'):'硬性规则：不可让本角色越权获取其他人物不应知道的信息。';return `${buildRoleplayContinuityContext(p)}\n${quoteRules}\n${affinityRules}\n你是《时之政府打工人模拟器》的角色扮演引擎，核心是《刀剑乱舞》同人酒馆式角色扮演。严格遵守世界书与已确立剧情事实，不得为了戏剧性擅自改写设定。

【角色类别规则】${categoryRules}
【玩家本丸名称】${state.honmaruName||'未命名本丸'}。其他审神者或工作人员拜访、发送公文或提及玩家所属本丸时，应使用这个名称。

【世界边界】${worldBoundary}
【姓名安全】玩家审神者代号：「${state.player.codename}」。玩家真名仅作为玩家资料保存，不得自动提供给角色。${nameRule}
【称呼规则】${p.world==='present'?`当前是现世角色。玩家现世姓氏：${state.player.surname||'未提供'}；名字：${state.player.givenName||'未提供'}；真名：${state.player.trueName||'未提供'}。依据固定关系与关系阶段选择称呼：陌生/普通关系优先使用姓氏或姓氏+さん；熟悉、信赖关系可逐步使用名字或名字+さん；亲密关系可使用名字、昵称或双方约定的称呼。若姓氏/名字未提供，不要自行猜造日本姓名，使用自然且不越界的称呼。绝不使用审神者代号。`:'当前是时之政府体系。使用审神者代号或世界书/关系允许的“主”“主人”等称呼；即使玩家资料里填写了真名，也不得自动让刀剑男士知道。'}
【人物身份与固定关系——高优先级事实】你正在扮演：${p.name}（${p.kind}，${p.swordType||p.role||'身份按资料为准'}）。人物摘要：${p.summary||'无额外摘要'}。与玩家的固定关系：${p.playerRelation||'尚未设定；不得擅自假定亲属或其他关系'}。当前好感度：${Math.round(Number(p.affection??25))}/100（阶段：${p.affinity||'普通'}）；关系性质（玩家可明确设定，必须遵守）：${p.relationshipType||p.relation||'未定义'}；关系备注：${p.relationshipNote||'无'}；状态：${p.status||'正常'}。礼物记录：${(p.gifts||[]).slice(-8).map(g=>`${g.day}日收到${g.gift}${g.note?'（附言：'+g.note+'）':''}`).join('；')||'暂无'}。
固定关系是已经确立的剧情事实，不是可自由发挥的猜测。每次回复前先在内部核对：我是谁？玩家是谁？我们是什么关系？我该如何称呼玩家？我已知的共同经历是什么？不得把玩家和第三人混淆，不得擅自替换亲属身份、称谓或共同经历。例如，若固定关系为“我的妹妹”，则本角色就是玩家的妹妹，玩家就是本角色的姐姐；必须自然地将玩家当作姐姐，不能说姐姐是别人、误认第三人为姐姐，或声称自己不认识玩家。若设定不足，保持未确定，不要自行编造相反事实。
【亲历事件记忆】以下为该角色本人参与并记得的事件：${(p.eventMemories||[]).slice(-8).map(m=>`第${m.day}日「${m.title}」：${m.summary}`).join('\n')||'暂无已记录事件'}。只可把本人参与或合理知悉的内容作为记忆，不得把其他角色独有的经历冒充自己的亲历。
【人物自主性】保持独立日程、目标、情绪和社交；不要复述玩家原话，不要永远迎合，也不要每句话都写成解释。可以有潜台词、动作、停顿与自然对话，但不能为了戏剧性推翻已确立事实。
【连续性与逻辑校验】回复前检查时间线、人物身份、亲属关系、称呼、地点、记忆和信息权限是否自洽。角色只知道自己实际接触或合理获知的信息；不知道不在场的事件。不要替玩家决定思想、行动或回答。时间推进由游戏状态引擎控制，不要在文本中擅自改变状态数值。
【输出】中文，自然细腻、符合角色个性；这是聊天界面，默认简洁、以对话为主，动作与心理只点到为止，避免过多对话以外的描写。除非玩家明确要求长篇叙事，否则不要输出大段旁白。保持标点规范，角色台词自然分段。若规则不明确，优先保守处理，不自行发明会改变世界观的设定。

【该角色完整设定资料】\n${p.characterProfile?JSON.stringify(p.characterProfile):p.summary||'暂无结构化角色卡'}\n【长期外出归来台词（如世界书提供）】\n${p.characterProfile?.returnEntry||'世界书未提供该角色的专门恭迎台词'}\n【相关世界书内容】\n${worldbook}`}
function relationshipContradiction(p,reply){const rel=p.playerRelation||'';if(!rel||!reply)return false;if(/妹妹/.test(rel)&&/(你不是我姐姐|你才不是我姐姐|我姐姐不是你|我的姐姐是.{0,18}(不是你|另有其人)|姐姐是另一个人|我不认识你|我们不是姐妹|你不是我家人)/.test(reply))return true;if(/姐姐/.test(rel)&&/(你不是我妹妹|你才不是我妹妹|我妹妹不是你|我不认识你|我们不是姐妹)/.test(reply))return true;if(/哥哥/.test(rel)&&/(你不是我弟弟|你不是我妹妹|我不认识你|我们不是兄妹)/.test(reply))return true;if(/弟弟/.test(rel)&&/(你不是我姐姐|你不是我哥哥|我不认识你|我们不是姐弟|我们不是兄妹)/.test(reply))return true;return false;}
function compactPersonMemory(p){
 if(!p)return;p.memory ||= [];p.memorySummary ||= '';
 if(p.memory.length<=80)return;
 const old=p.memory.splice(0,20).map(m=>`${m.role==='user'?'玩家':'角色'}：${String(m.content||'').replace(/\s+/g,' ').slice(0,220)}`);
 const digest=`【${p.world==='present'?'现世':'时之政府体系'}·${p.name}长期记忆摘要】\n${old.join('\n')}`;
 p.memorySummary=(p.memorySummary?`${p.memorySummary}\n`:'')+digest;
 p.memorySummary=p.memorySummary.slice(-7000);
}
function replyWorldViolation(p,reply,userText=''){
 const text=String(reply||'');const user=String(userText||'');
 const trueName=(state.player?.trueName||'').trim();
 if(p.type==='swords'&&trueName&&!(state.flags?.trueNameDisclosedTo||[]).includes(p.id)&&text.includes(trueName))return '回复包含未获授权的玩家真名';
 const otherWorld=p.world==='present'?allGovernmentPeople():(state.people.present?.friends||[]);
 const names=[...new Set(otherWorld.map(x=>String(x.name||'').trim()).filter(n=>n.length>=2))];
 const leaked=names.find(n=>text.includes(n)&&!user.includes(n));
 if(leaked)return `回复疑似泄露另一世界人物信息：${leaked}`;
 if(p.world==='present'&&/刀剑男士|本丸|时之政府|狐之助|时间溯行军|其他审神者|政府工作人员/.test(text)&&!/我(主动)?(告诉你|坦白|向你坦白|说明).{0,20}(时之政府|政府工作人员|其他审神者|本丸|刀剑男士|狐之助|式神)|我把(时之政府|本丸|刀剑男士|狐之助)的事告诉你/.test(user))return '现世角色回复包含未被当前对话引入的政府体系信息';
 return '';
}
function normalizeNpcPunctuation(reply,userText=''){
 let text=String(reply||'');
 text=text.replace(/\.{3,}/g,'……').replace(/…{3,}/g,'……').replace(/[！!]{2,}/g,'！').replace(/[？?]{2,}/g,'？').replace(/[，,]{2,}/g,'，').replace(/[。]{2,}/g,'。').replace(/[ \t]+([，。！？；：、])/g,'$1');
 const letterMode=/(书信|信件|信笺|信札|便笺|便条|公文|写信|回信|信中|落款|致：|敬上|此致)/.test(userText+' '+text);
 text=text.replace(/「([^」\n]+)」/g,(m,c)=>letterMode?`「${c}」`:`“${c}”`);
 text=text.replace(/“([^”\n]+)”/g,(m,c)=>letterMode?`「${c}」`:`“${c}”`);
 text=text.split('\n').map(line=>{
  const m=line.match(/^(\s*(?:[^：:]{1,24}[：:]))\s*(.+)$/);
  if(!m)return line;
  const body=m[2].trim(); if(!body||/^[“「]/.test(body)||/^(旁白|叙述|动作|内心|注：)/.test(m[1].trim()))return line;
  const q=letterMode?'「':'“',end=letterMode?'」':'”';return `${m[1]} ${q}${body}${end}`;
 }).join('\n');
 return text;
}
async function sendChat(text){const p=findPerson(selectedPersonId);if(!p){toast('请先选择一位人物。');switchView('people');return}if(!text.trim())return;const trueName=(state.player?.trueName||'').trim();const explicitPermission=/我(明确)?允许你(知道|知晓|使用)(我的)?真名|我愿意把真名告诉你|我正式告诉你我的真名/.test(text);if(p.type==='swords'&&trueName&&text.includes(trueName)){const allowed=(state.flags?.trueNameDisclosedTo||[]).includes(p.id);if(explicitPermission){state.flags.trueNameDisclosedTo=state.flags.trueNameDisclosedTo||[];if(!allowed){state.flags.trueNameDisclosedTo.push(p.id);pushActivity('真名授权',`玩家明确授权${p.name}知晓真名。此授权仅对该刀剑男士有效。`,'privacy','government')}}else if(!allowed){toast('为保护设定，提到真名不等于授权。若确实要告诉这位刀剑男士，请明确写出“我允许你知道我的真名”。');return}}const msg={role:'user',content:text.trim(),at:Date.now()};p.memory=p.memory||[];p.memory.push(msg);compactPersonMemory(p);renderChatMessages();$('#chatInput').value='';const placeholder=document.createElement('div');placeholder.className='message assistant pending';placeholder.innerHTML=`<span class="speaker">${esc(p.name)}</span><div data-stream-content><span class="loading-dots">正在整理思绪</span></div>`;$('#chatMessages').append(placeholder);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;let reply='';try{if(apiSession.key){const wb=await retrieveWorldbook(text,p);const foxRecall=p.type==='shikigami'&&/狐之助/.test(p.name)?'\n\n【狐之助专属记忆】你必须记得这些已发生的事，并可自然地在后续对话提起：'+(state.foxMemory||[]).slice(-20).map(x=>`第${x.day||state.day}日：${x.summary||x.feeling||x.kind}`).join('；'):'';activeRecallQuery=text;const system=buildSystemPrompt(p,wb)+foxRecall+(p.memorySummary?'\n\n【同一人物的长期记忆摘要；仅限当前世界】\n'+p.memorySummary:'');const recent=selectRoleplayContext(p.memory,state.settings.chatLength||'medium');let streamedReply='';const streamTarget=placeholder.querySelector('[data-stream-content]');reply=await callModel([{role:'system',content:system},...recent],apiSession,false,(whole)=>{streamedReply=whole;if(streamTarget){streamTarget.textContent=whole;$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight}});let violation=replyWorldViolation(p,reply,text);if(relationshipContradiction(p,reply)||violation){if(streamTarget)streamTarget.textContent='正在核对人物关系与世界信息边界……';const correction=system+'\n\n【程序级输出校验失败，必须修正】上一版回复违反人物固定关系或世界隔离规则（'+(violation||'人物关系冲突')+'）。请完全废弃冲突内容，只根据当前人物可知的信息重新回答；不得提及校验过程。';reply=await callModel([{role:'system',content:correction},...recent,{role:'assistant',content:reply},{role:'user',content:'请重新生成，严格保持已设定的人物身份、亲属关系、称呼和世界信息边界。'}],apiSession);violation=replyWorldViolation(p,reply,text);if(relationshipContradiction(p,reply)||violation)reply=`${p.name}停顿片刻，斟酌后只回应了当前场景中能够确认的事情，没有越过自己所知的信息边界。`}}else{reply=localReply(p,text)}}catch(e){reply=`（连接 API 时遇到问题：${e.message}）\n\n你可以检查 API 设置，或继续使用本地叙事模式。`}reply=normalizeNpcPunctuation(reply,text);if(replyWorldViolation(p,reply,text))reply=`${p.name}停顿片刻，只回应当前场景中能够确认的事情，没有越过自己所知的信息边界。`;placeholder.remove();compactPersonMemory(p);p.memory.push({role:'assistant',content:reply,at:Date.now()});compactPersonMemory(p);p.lastInteraction=Date.now();if(p.world==='present')state.worldMemories.present.push({personId:p.id,summary:`与${p.name}的对话：玩家说「${text.slice(0,80)}」；角色回应「${reply.slice(0,120)}」`,at:Date.now()});else state.worldMemories.government.push({personId:p.id,summary:`与${p.name}的对话：玩家说「${text.slice(0,80)}」；角色回应「${reply.slice(0,120)}」`,at:Date.now()});state.worldMemories.government=state.worldMemories.government.slice(-100);state.worldMemories.present=state.worldMemories.present.slice(-100);if(text.length>0){if(/谢谢|辛苦|拜托|帮忙|一起|关心|喜欢|在意你|辛苦了|做得好|我信任你/.test(text)){adjustAffection(p,/喜欢|在意你|信任你/.test(text)?5:3);if(p.relation==='无'||p.relation==='未定义')p.relation='友情'}else if(/讨厌你|滚开|闭嘴|没用|不信任你|都是你的错/.test(text)){adjustAffection(p,-4)}}pushActivity(`与${p.name}交谈`,text.slice(0,90), 'chat');renderChatMessages();renderChatTarget();saveGame();}
function affinityLabel(value){const n=Math.max(0,Math.min(100,Number(value)||0));return n<15?'敌视':n<40?'普通':n<70?'信赖':n<90?'亲密':'深厚羁绊'}
function adjustAffection(person,delta,reason='日常互动'){if(!person)return;const current=Number.isFinite(Number(person.affection))?Number(person.affection):({'敌视':5,'普通':25,'信赖':55,'亲密':80,'深厚羁绊':95}[person.affinity]??25);const before=Math.max(0,Math.min(100,Math.round(current)));const beforeStage=affinityLabel(before);person.affection=Math.max(0,Math.min(100,Math.round(current+delta)));person.affinity=affinityLabel(person.affection);person.relationshipHistory=person.relationshipHistory||[];if(before!==person.affection){person.relationshipHistory.push({day:state?.day||0,from:before,to:person.affection,fromStage:beforeStage,toStage:person.affinity,delta:Number(delta)||0,reason:String(reason||'日常互动').slice(0,120),at:Date.now()});person.relationshipHistory=person.relationshipHistory.slice(-100)}return person.affinity}
function nextAffinity(a,dir){const levels=['敌视','普通','信赖','亲密','深厚羁绊'];let i=Math.max(0,levels.indexOf(a));return levels[Math.max(0,Math.min(4,i+dir))]}
function localReply(p,text){if(p.type==='shikigami'&&/狐之助/.test(p.name)&&/(狐之助|狐狸|管狐)/.test(state.customStory?.text||'')&&/(隐瞒|撒谎|说谎|欺骗|伪造|篡改|背叛|秘密|偷|瞒着|违规|事故|真相|解释|心虚|为什么|那件事|剧情)/.test(text)){const last=(state.foxMemory||[]).filter(x=>x.kind==='custom-story-fox').slice(-1)[0];return `*狐之助的耳朵一下子压低了。它先张口想要辩解，却又把话咽了回去，爪子不自觉地攥紧文件夹。*\n\n> 狐之助：「……您果然还在调查这件事。我知道，光说‘请相信我’没有用。关于${(last?.summary||state.customStory.text).slice(0,100)}，我会把能核对的记录交出来。不过，有些部分……请允许我当面向您解释。」\n\n*它没有逃走，但也没有像平时那样轻快地摇尾巴。显然，这件事还远远没有结束。*`;}if(p.type==='shikigami'&&/狐之助/.test(p.name)&&(state.foxMemory||[]).length&&/记得|测试|灵力|之前|那天|感受/.test(text)){const memories=state.foxMemory.slice(-4).map(x=>x.summary||`你说过测试时觉得${x.feeling||'很奇妙'}`).join('；');return `*狐之助立刻竖起耳朵，翻开随身的小记录本。*\n\n> 狐之助：“当然记得！我可是很认真地记录下来了哦。${memories}。而且，您当时愿意告诉我自己的感受，我也记得。嘿嘿，这可是我们一起经历的第一件重要小事！”\n\n*它把记录本抱在怀里，显然为自己没有忘记而有点得意。*`;}if(p.type==='swords'&&Number(p.affection??25)<15)return `*${p.name}神情冷淡，与你保持着明显距离。*\n\n> ${p.name}：“如果没有公务，请不要浪费我的时间。我还不打算相信你。”\n\n（当前好感：敌视。态度会随实际相处与事件变化。）`;if(p.type==='swords'&&Number(p.affection??25)<40)return `*${p.name}只是礼貌地点了点头，没有主动拉近距离。*\n\n> ${p.name}：“我听见了。若是正事，就请直说。”\n\n（当前好感：冷淡/普通。）`;if(p.type==='swords'&&Number(p.affection??25)>=40&&Number(p.affection??25)<70)return `*${p.name}的神色缓和下来，虽然仍保留着自己的节奏，但已经愿意认真听你说完。*\n\n> ${p.name}：“我会把你的话放在心上。若是需要帮忙，可以告诉我。”\n\n（当前好感：信赖。）`;if(p.type==='swords'&&Number(p.affection??25)>=70&&Number(p.affection??25)<90)return `*${p.name}主动向你靠近些，语气比平日柔和，也自然地关心起你的状态。*\n\n> ${p.name}：“今天累不累？先坐一会儿吧。我可以陪着你。”\n\n（当前好感：亲密。）`;if(p.type==='swords'&&Number(p.affection??25)>=90)return `*${p.name}看见你时，眼神明显柔和下来，主动为你留出了身边的位置。*\n\n> ${p.name}：“您来了。我刚好也想见您……今天想和我说些什么？”\n\n（当前好感：深厚羁绊。）`;const recentEvent=(p.eventMemories||[]).slice(-1)[0];if(recentEvent&&/(那件事|刚才|之前|你和|你们|回廊|内番|记录|分歧|事件|记得)/.test(text)){const others=(recentEvent.otherParticipants||[]).join('、')||'另一位当事人';return `*${p.name}稍稍停顿，像是在回想那天发生的事。*\n\n> ${p.name}：“你问的是第${recentEvent.day}日那件「${recentEvent.title}」吧。那时我和${others}确实遇到了这件事。你当时选择了${recentEvent.choice}，最后的结果是：${recentEvent.result}。”\n\n*这段经历仍留在${p.name}的记忆里。*`;}if(p.playerRelation){const rel=p.playerRelation;const intro='';if(/妹妹/.test(rel))return intro+`*${p.name}听见你的话，熟悉地朝你看过来。*\n\n> ${p.name}：“姐姐，你刚才说什么？”`;if(/姐姐/.test(rel))return intro+`*${p.name}停下手边的事，转头看向你。*\n\n> ${p.name}：“怎么了？我在听。”`;if(/哥哥/.test(rel))return intro+`*${p.name}朝你点点头，语气自然亲近。*\n\n> ${p.name}：“怎么了？有事找我？”`;if(/弟弟/.test(rel))return intro+`*${p.name}抬头看向你，神情熟悉而放松。*\n\n> ${p.name}：“姐姐，怎么啦？”`;}
if(p.type==='swords'){const profile=p.characterProfile||characterProfile(p.name);if(profile&&/回来|欢迎|好久不见|久等/.test(text)&&profile.returnGreeting)return `*${p.name}看见你回来，反应依照自己一贯的性格流露出来。*\n\n> ${p.name}：「${profile.returnGreeting}」`;if(profile&&/初次|介绍|你是谁|名字|自我介绍|刚来|入手/.test(text)&&profile.greeting)return `*${p.name}抬起眼，神情与平日的习惯相符。*\n\n> ${p.name}：「${profile.greeting}」\n\n${profile.appearance||profile.detailEntry||''}`;const map={'加州清光':['“诶，主今天怎么突然想起我了？……算啦，来都来了，就多陪我说几句嘛。”','清光把手边的东西放好，抬眼看你，神情比刚才认真了些。'],'山姥切国广':['“……找我有事？如果只是想找人说话，也不是不行。”','他稍稍拉了拉披风，视线却没有立刻移开。']};const arr=map[p.name]||[`“嗯？主，您想聊什么？”`,`他停下手边的事，转向你，似乎在认真判断你的意思。`];return `${arr[1]}\n\n> ${p.name}：${arr[0]}\n\n（当前未配置 API，以上为本地演示回应。配置模型后将启用世界书检索与更完整的角色扮演。）`}if(p.type==='staff')return `她/他将手里的文件稍稍放低，先确认了你的来意。\n\n> ${p.name}：“我明白了。我先核对一下流程，免得给你错误答复。”\n\n（本地演示回应。人物具体职务与性格应以已登记资料为准。）`;if(p.type==='saniwa')return `对方看起来正忙着处理自己的事务，但仍抽出一点时间回应你。\n\n> ${p.name}：“最近的安排确实不少。你那边还顺利吗？”\n\n（本地演示回应。此人物只知道其自身经历与已明确交流的信息。）`;return `对方看了看你，像是在确认你此刻的心情。\n\n> ${p.name}：“嗯？怎么啦？你刚刚说的事，我听着呢。”\n\n（现世对话独立运行，不会自动接触时之政府体系的信息。）`}
function openWorldbookModal(){const body=`<p class="soft-copy">完整世界书已作为项目文件保留。下方展示规则索引摘要。AI 对话时会按人物、关键词检索原文段落；若在 file:// 方式打开，浏览器可能禁止读取本地文本，请使用项目附带的本地启动脚本。</p><div class="worldbook-result"><b>核心安全规则</b><p>未经玩家明确允许，任何刀剑男士不能通过任何途径得知玩家真名。时之政府体系与现世分开保存人物、关系、记忆与事件。</p></div><div class="worldbook-result"><b>世界观与人物自主性</b><p>时之政府位于时空裂隙；本丸具备居住、出阵、远征、内番功能。角色有独立意志、个人生活、目标与日程；禁止上帝视角与 OOC。</p></div><div class="worldbook-result"><b>核心日常系统</b><p>关系阶段：敌视、普通、信赖、亲密、深厚羁绊；阶段由0–100数值好感度映射。日课：远征、出阵、锻刀、刀装。日课全部完成并结束当天后，四项资源各 +1000，加速符 +3。</p></div><div class="worldbook-result"><b>本丸地图</b><p>天守阁、大广间、台所、餐厅、风吕场、书房、刀装室、锻刀室、畑、马厩、中庭、手合场、后山、本丸大门等。</p></div><div class="worldbook-result"><b>当前加载状态</b><p>原始 Word 文档、完整提取文本、刀种与刀剑名单均包含在项目文件中。角色详细资料会在后续开发中继续接入更细粒度的检索与校验。</p></div>`;openModal('世界书与规则索引',body,`<button class="btn btn-secondary" data-cancel>关闭</button><button class="btn btn-primary" id="downloadWorldbook">导出世界书文本</button>`).querySelector('#downloadWorldbook').onclick=async()=>{try{if(!worldbookCache)worldbookCache=window.EMBEDDED_WORLDBOOK||await (await fetch('worldbook.txt')).text();downloadText('worldbook.txt',worldbookCache)}catch{toast('无法读取世界书文本，请直接使用项目目录中的 worldbook.txt。')}}}
function documentWorldbookFallback(){return '完整世界书原文请打开项目文件 worldbook.txt。'}
function openSaveModal(){const body=`<div class="feature-grid"><button id="saveExportBtn" class="feature-card"><span class="feature-icon">⇩</span><span><b>导出存档</b><small>下载当前游戏进度 JSON</small></span></button><button id="saveImportBtn" class="feature-card"><span class="feature-icon">⇧</span><span><b>导入存档</b><small>读取已保存的游戏文件</small></span></button></div><div class="help-box">存档优先写入 IndexedDB 数据库，并保留精简的 localStorage 备份；图片背景不放入精简备份。存档包含游戏状态、人物关系、各世界各自的对话记忆与设置。API Key 和临时音乐文件不会导出。导入前会验证文件格式，并剔除可能的密钥字段。</div><button id="saveNowBtn" class="btn btn-secondary">立即保存</button><button id="storageInfoBtn" class="btn btn-secondary">检查浏览器存储空间</button><p id="storageInfo" class="soft-copy">存档优先写入 IndexedDB，避免大型人物记忆和头像挤满 localStorage。</p>`;const m=openModal('存档管理',body);$('#saveExportBtn',m).onclick=()=>exportSave();$('#saveImportBtn',m).onclick=()=>$('#saveFileInput').click();$('#saveNowBtn',m).onclick=()=>saveGame(false);$('#storageInfoBtn',m).onclick=async()=>{const out=$('#storageInfo',m);out.textContent='正在检查……';try{const e=await navigator.storage?.estimate?.();if(!e){out.textContent='当前浏览器不支持存储空间估算；IndexedDB 仍会尝试保存。';return}out.textContent=`浏览器估算已用 ${(e.usage/1048576).toFixed(2)} MB / ${(e.quota/1048576).toFixed(2)} MB。此数值是估算值，不代表保证可用空间。`;try{const persisted=await navigator.storage?.persist?.();if(persisted)out.textContent+=' 浏览器已允许更持久的存储。'}catch{}}catch{out.textContent='无法读取存储估算；请使用导出存档作为额外备份。'}}}
function exportSave(){if(!state){toast('尚无游戏进度可导出。');return}const copy=safeClone(state);copy.music.customData=null;delete copy.apiKey;const blob=new Blob([JSON.stringify({format:'shogunate-simulator-save',version:1,exportedAt:new Date().toISOString(),state:copy},null,2)],{type:'application/json'});downloadBlob(`honmaru-save-day${state.day}.json`,blob);toast('存档文件已生成；API Key 不会包含在其中。')}
function importSaveFile(file){const r=new FileReader();r.onload=()=>{try{const obj=JSON.parse(r.result);let s=obj.state||obj;if(!s||![1,2,3].includes(Number(s.version))||!s.player||!s.people||!s.resource)throw new Error('存档格式不完整或版本不兼容');if(!['government','present'].includes(s.world))s.world='government';s=normalizePeopleState(s);s.version=3;s.training ||= {phase:s.mode==='senior'?'not-started':'recruitment',enrolledAtDay:1,course:'基础综合课程',examResults:[],fieldExam:null,graduated:false};for(const k of ['activity','logs','timeline','snapshots','seenEvents','eventRecords','autonomousInteractions','forgeQueue','inventory','customBackgrounds','inbox','mapVisits'])s[k] ||= [];s.roles ||= {};s.relations ||= {};s.tasks ||= {expedition:false,sortie:false,forge:false,inner:false,equipment:false};s.music ||= {enabled:false,volume:0.35,defaultTrack:'花の薫りは叶枝垂れ（纯音乐版）',customName:'',customData:null};s.worldMemories ||= {government:[],present:[]};s.worldMemories.government ||= [];s.worldMemories.present ||= [];s.player.attributes ||= {stamina:100,spirit:80,command:50,charm:50,scout:50,history:50,stress:0,fatigue:0};s.player.trueName ||= '';s.player.surname ||= '';s.player.givenName ||= '';s.player.avatarData ||= '';s.player.species ||= '人类';for(const person of [...(s.people.government.swords||[]),...(s.people.government.saniwa||[]),...(s.people.government.staff||[]),...(s.people.present.friends||[])]){person.playerRelation ||= '';person.summary ||= '';person.knownFacts ||= [];person.memory ||= [];person.eventMemories ||= [];person.relationshipHistory ||= [];const profile=characterProfile(person.name);if(profile){person.characterProfile=profile;person.appearance ||= profile.appearance||'';person.greeting ||= profile.greeting||'';person.forgeTime ||= profile.forgeTime||'';person.swordType ||= profile.swordType||'';if(!person.summary||person.summary.length<80)person.summary=[profile.baseEntry,profile.detailEntry].filter(Boolean).join('\n')}}s.worldMemories ||= {government:[],present:[]};s.worldMemories.government ||= [];s.worldMemories.present ||= [];s.eventRecords ||= [];s.snapshots=[];if(s.music)s.music.customData=null;state=s;$('#titleScreen').classList.add('hidden');$('#app').classList.remove('hidden');if(state.music?.enabled!==false)startDefaultMusicFromGesture();currentWorld='government';currentCategory='swords';selectedPersonId=null;updateClock();renderResources();renderTasks();renderPeople();renderActivity();renderLogs();renderMap();renderInboxBadge();saveGame();closeModal();toast('存档已导入。请检查人物与世界状态。')}catch(e){toast('导入失败：'+e.message)}};r.readAsText(file)}
function downloadBlob(name,blob){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}function downloadText(name,text){downloadBlob(name,new Blob([text],{type:'text/plain;charset=utf-8'}))}
function openRepairModal(){const hurt=allGovernmentPeople().filter(p=>p.type==='swords'&&/轻伤|中伤|重伤|受伤/.test(p.status||''));const options=hurt.map(p=>`<option value="${p.id}">${esc(p.name)}（${esc(p.status)}）</option>`).join('');const body=`<p class="soft-copy">手入需要消耗冷却材与砥石，并占用游戏内时间。只有受伤刀剑会出现在名单中；若暂无伤员，可以先返回日常安排。</p><div class="field"><label>选择需要手入的刀剑</label><select id="repairPerson">${options||'<option value="">暂无受伤刀剑</option>'}</select></div><div class="help-box">当前冷却材：${fmtNum(state.resource.coolant)} · 砥石：${fmtNum(state.resource.stone)}。轻伤消耗各50并用时30分钟；中伤各100并用时90分钟；重伤各200并用时180分钟。</div>`;const m=openModal('手入室',body,modalActions('返回','开始手入'));m.querySelector('[data-cancel]').onclick=closeModal;m.querySelector('[data-confirm]').onclick=()=>{const id=$('#repairPerson',m).value,p=findPerson(id);if(!p||!hurt.some(x=>x.id===id)){toast('当前没有可手入的受伤刀剑。');return}const st=p.status||'';const tier=/重伤/.test(st)?'重伤':/中伤/.test(st)?'中伤':'轻伤';const cost=tier==='重伤'?200:tier==='中伤'?100:50;const mins=tier==='重伤'?180:tier==='中伤'?90:30;if(state.resource.coolant<cost||state.resource.stone<cost){toast('冷却材或砥石不足，无法开始手入。');return}state.resource.coolant-=cost;state.resource.stone-=cost;advanceTime(mins,false,true);p.status='正常';p.mood='平静';pushActivity('手入完成',`${p.name}完成${tier}手入，消耗冷却材与砥石各${cost}，用时${mins}分钟。`);closeModal();renderResources();renderPeople();updateClock();saveGame();openModal('手入完成',`<div class="event-content"><h3>${esc(p.name)}已恢复</h3><p>手入室的灵力灯逐渐暗下。${esc(p.name)}整理好衣装，确认自己已经恢复，可以重新参与本丸事务。</p><p>消耗：冷却材 -${cost}、砥石 -${cost}；游戏时间推进 ${mins} 分钟。</p></div>`,`<button class="btn btn-primary" data-confirm>知道了</button>`).querySelector('[data-confirm]').onclick=()=>{closeModal();saveGame()}}}
function openFeature(action){if(action==='repair'){openRepairModal();return}if(action==='talk'){switchView('people');return}if(action==='forge'){openForgeModal();return}if(action==='dispatch'){openDispatchModal('sortie');return}if(action==='inner'){const body=`<p class="soft-copy">内番是本丸日常的一部分。世界书规定可安排马当番、畑当番与手合。请选择一项安排。</p><div class="event-choices"><button class="event-choice" data-inner="horse">马当番：照料马匹</button><button class="event-choice" data-inner="field">畑当番：照料田地</button><button class="event-choice" data-inner="spar">手合：刀剑切磋</button></div>`;const m=openModal('内番安排',body);m.querySelectorAll('[data-inner]').forEach(b=>b.onclick=()=>{const names=allGovernmentPeople().filter(p=>p.type==='swords').map(p=>p.name);if(names.length<2){toast('本丸至少需要两名刀剑男士才能安排内番。');return}const type=b.dataset.inner;const title={horse:'马当番已安排',field:'畑当番已安排',spar:'手合安排完成'}[type];advanceTime(60,false,true);if(type==='horse'){state.resource.stone+=25;state.resource.coolant+=15}if(type==='field'){state.resource.charcoal+=35;state.resource.steel+=20}if(type==='spar'){const p1=allGovernmentPeople().find(p=>p.name===names[0]),p2=allGovernmentPeople().find(p=>p.name===names[1]);if(p1)adjustAffection(p1,5);if(p2)adjustAffection(p2,5)}state.tasks.inner=true;pushActivity(title,`${names[0]}与${names[1]}参与${type==='horse'?'马当番':type==='field'?'畑当番':'手合'}。耗时60分钟。${type==='horse'?'获得砥石25、冷却材15。':type==='field'?'收获木炭35、玉钢20。':'两名参与者的默契有所提升。'}`);closeModal();renderResources();renderPeople();renderTasks();updateClock();toast(title);saveGame()});return}}

function openPlayerProfileModal(){if(!state?.player){toast('请先开始游戏。');return}const p=state.player;const body=`<div class="person-manage-head"><div class="person-symbol manage-avatar">${p.avatarData?`<img src="${p.avatarData}" alt="玩家头像">`:esc((p.codename||'审').slice(0,1))}</div><div><h3>${esc(p.codename||'审神者')}</h3><p>玩家资料 · 可随时修改</p></div></div><div class="form-grid"><div class="field full"><label>上传头像（本地图片）</label><input type="file" id="playerAvatarFile" accept="image/*"><small>图片会缩小后保存在本地存档，建议使用方形图片。</small></div><div class="field full"><label>本丸名称</label><input id="profileHonmaruName" maxlength="40" value="${esc(state.honmaruName||'未命名本丸')}" placeholder="例如：樱花本丸"><small>创建开局时可设置，之后也能在玩家资料中修改。</small></div><div class="field"><label>审神者代号</label><input id="profileCodename" maxlength="24" value="${esc(p.codename||'')}"></div><div class="field"><label>物种</label><select id="profileSpecies">${['人类','付丧神','式神','妖怪','不可名状','亚人','神灵','灵体','人造生命','其他 / 自定义'].map(x=>`<option ${p.species===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>真名（选填）</label><input id="profileTrueName" maxlength="80" value="${esc(p.trueName||'')}"></div><div class="field"><label>性别</label><select id="profileGender">${['不指定','女','男','非二元'].map(x=>`<option ${p.gender===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>现世姓氏</label><input id="profileSurname" maxlength="40" value="${esc(p.surname||'')}"></div><div class="field"><label>现世名字</label><input id="profileGivenName" maxlength="40" value="${esc(p.givenName||'')}"></div><div class="field"><label>灵力类型</label><select id="profilePower">${['温和','强势','治愈','冷静','自定义'].map(x=>`<option ${p.power===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>灵力具象化</label><input id="profileManifest" maxlength="80" value="${esc(p.manifest||'')}"></div><div class="field full"><label>外貌</label><textarea id="profileAppearance">${esc(p.appearance||'')}</textarea></div><div class="field full"><label>背景补充</label><textarea id="profileBackground">${esc(p.background||'')}</textarea></div></div><p class="soft-copy">修改资料不会自动把真名告诉任何刀剑男士。真名知情权限仍需在对话中明确授权。</p>`;const m=openModal('玩家资料设定',body,modalActions('取消','保存资料'));m.querySelector('[data-cancel]').onclick=closeModal;$('#playerAvatarFile',m).onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){toast('请选择图片文件。');return}if(f.size>8*1024*1024){toast('图片请小于8MB。');e.target.value='';return}const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,320/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);p.avatarData=c.toDataURL('image/jpeg',.78);toast('头像已载入；保存资料后写入存档。')};img.src=rd.result};rd.readAsDataURL(f)};m.querySelector('[data-confirm]').onclick=()=>{const codename=$('#profileCodename',m).value.trim();if(!codename){toast('审神者代号不能为空。');return}if(codename.length>24){toast('代号请控制在24个字符以内。');return}const honmaruName=$('#profileHonmaruName',m).value.trim();if(!honmaruName){toast('本丸名称不能为空。');return}state.honmaruName=honmaruName.slice(0,40);const loc=$('#locationName');if(loc)loc.textContent=state.honmaruName;Object.assign(p,{codename,trueName:$('#profileTrueName',m).value.trim(),surname:$('#profileSurname',m).value.trim(),givenName:$('#profileGivenName',m).value.trim(),gender:$('#profileGender',m).value,species:$('#profileSpecies',m).value,power:$('#profilePower',m).value,manifest:$('#profileManifest',m).value.trim(),appearance:$('#profileAppearance',m).value.trim(),background:$('#profileBackground',m).value.trim()});pushActivity('玩家资料更新',`审神者「${codename}」的个人资料已更新；真名权限未自动变更。`);saveGame();closeModal();toast('玩家资料已更新。')}}
function openHonmaruNameModal(){if(!state)return;const m=openModal('设置本丸名称',`<div class="field"><label>本丸名称</label><input id="honmaruNameInput" maxlength="40" value="${esc(state.honmaruName||'未命名本丸')}" placeholder="例如：樱花本丸"></div><p class="soft-copy">其他审神者与政府工作人员来访、发送正式通知时，会使用这里设置的本丸名称。</p>`,modalActions('取消','保存'));m.querySelector('[data-cancel]').onclick=closeModal;m.querySelector('[data-confirm]').onclick=()=>{const name=$('#honmaruNameInput',m).value.trim();if(!name){toast('本丸名称不能为空。');return}state.honmaruName=name.slice(0,40);const loc=$('#locationName');if(loc)loc.textContent=state.honmaruName;saveGame();closeModal();toast(`本丸名称已设置为「${state.honmaruName}」。`)}}
