function handleOfflineElapsed(){if(!state||state.stage!=='playing')return;const now=Date.now(),last=Number(state.lastWallClock||now),elapsed=Math.max(0,Math.min(12*60*60*1000,now-last));if(!state.paused&&settings.autoTime!==false){const mins=Math.floor(elapsed/60000*Math.max(0.25,Math.min(4,Number(state.speed)||1))); if(mins){advanceSimulationMinutes(mins,'离线时间结算');processTrainingMilestones();}}syncRealClock();saveGame();}
function setupListeners(){ $$('.quick').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$$('[data-action]').forEach(b=>b.onclick=()=>openFeature(b.dataset.action));$('#menuToggle').onclick=()=>$('#menuDrawer').classList.remove('hidden');$('#returnTitle').onclick=returnToTitle;if($('#playerProfileSettings'))$('#playerProfileSettings').onclick=()=>{ $('#menuDrawer').classList.add('hidden');openPlayerProfileModal()};$('#clearPlayerData').onclick=clearPlayerData;$('#clearTitleData').onclick=clearPlayerData;document.addEventListener('visibilitychange',()=>{if(document.hidden){if(state)state.hiddenAt=Date.now();saveGame()}else{if(state&&state.hiddenAt)state.lastWallClock=state.hiddenAt;handleOfflineElapsed();state.hiddenAt=null}});window.addEventListener('pagehide',()=>{if(state){state.hiddenAt=Date.now();saveGame()}});$$('[data-close-drawer]').forEach(b=>b.onclick=()=>$('#menuDrawer').classList.add('hidden'));$$('[data-open]').forEach(b=>b.onclick=()=>{const what=b.dataset.open;$('#menuDrawer').classList.add('hidden');if(what==='settings')openSettingsModal();if(what==='api')openApiModal();if(what==='people')switchView('people');if(what==='worldbook')openWorldbookModal();if(what==='saves')openSaveModal()});$('#newGame').onclick=()=>{openSetupModal()};if($('#openCustomStory'))$('#openCustomStory').onclick=openCustomStoryModal;$('#continueGame').onclick=async()=>{const s=await hydrateSaveFromIndexedDB();if(!s){toast('暂时没有可继续的存档。');return}state=s;if(state.music?.enabled===false)$('#bgmAudio').pause();else {state.music.enabled=true;startDefaultMusicFromGesture()}handleOfflineElapsed();$('#titleScreen').classList.add('hidden');$('#app').classList.remove('hidden');updateClock();renderResources();renderTasks();renderPeople();renderActivity();renderLogs();renderMap();renderInboxBadge();toast('已载入本地存档。')};$('#importTitle').onclick=()=>$('#saveFileInput').click();$('#openSettingsTitle').onclick=()=>{if(!state)state=baseState();openApiModal()};$('#brandHome').onclick=()=>switchView('home');$('#sceneInteract').onclick=()=>{petalBurst(window.innerWidth*.45,window.innerHeight*.45);switchView('chat');if(!selectedPersonId){currentWorld='government';currentCategory='swords';renderPeople();toast('请从人物列表选择一位人物开始互动。');switchView('people')}};$('#pauseTime').onclick=()=>{state.paused=!state.paused;updateClock();saveGame();toast(state.paused?'游戏时间已暂停。':'游戏时间继续推进。')};$('#rewindTime').onclick=rewind;$('#fastTime').onclick=()=>{snapshot();advanceSimulationMinutes(120,'手动快进');processTrainingMilestones();updateClock();saveGame();if(state.settings.randomEvents)maybeRandomEvent(false);toast('模拟时间已快进两小时；设备时间未改变。')};$('#endDay').onclick=endDay;if($('#openTraining'))$('#openTraining').onclick=()=>state.mode==='senior'||state.training?.graduated?openSeniorAssignmentModal(!!state.training?.graduated):openTrainingModal();if($('#openForge'))$('#openForge').onclick=openForgeModal;$('#addPerson').onclick=openAddPersonModal;$('#chatChangeTarget').onclick=()=>switchView('people');$('#refreshHome').onclick=()=>{renderActivity();renderMap();renderInboxBadge();toast('本丸记录已更新。')};$('#openInbox').onclick=openInboxModal;$('#chatForm').onsubmit=e=>{e.preventDefault();const text=$('#chatInput').value;sendChat(text)};$('#chatInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chatForm').requestSubmit()}});$('#exportSave').onclick=exportSave;$('#saveFileInput').onchange=e=>{if(e.target.files[0])importSaveFile(e.target.files[0]);e.target.value=''};$('#bgFileInput').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>12*1024*1024){toast('图片过大，请选择小于12MB的图片。');return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.78),id='custom-'+uid();state.customBackgrounds.push({id,name:f.name,data});state.backgroundId=id;state.backgroundMode='manual';setSceneBackground(data);saveGame();toast('自定义背景已压缩并应用。')};img.onerror=()=>toast('无法读取这张图片，请换一张图片重试。');img.src=reader.result};reader.readAsDataURL(f);e.target.value=''};document.addEventListener('pointerdown',()=>{if(state?.stage==='playing'&&state.music?.enabled!==false){const a=$('#bgmAudio');if(a&&a.paused)startDefaultMusicFromGesture()}},{passive:true});$('#musicFileInput').onchange=e=>{const f=e.target.files[0];if(!f)return;if(musicObjectUrl)URL.revokeObjectURL(musicObjectUrl);musicObjectUrl=URL.createObjectURL(f);const a=$('#bgmAudio');a.src=musicObjectUrl;a.volume=state.music.volume;state.music.customName=f.name;state.music.enabled=true;const fail=()=>{state.music.enabled=false;toast('浏览器无法解码该音频。若文件来自音乐平台，可能是加密封装；请改用可正常播放的标准 MP3、M4A、OGG 或 FLAC 文件。')};a.onerror=fail;a.play().then(()=>toast(`正在播放：${f.name}`)).catch(()=>{state.music.enabled=false;toast('无法播放该音频。请确认格式受浏览器支持，且文件不是平台加密格式。')});e.target.value=''};document.addEventListener('click',e=>{if(e.target.closest('input,textarea,select,[contenteditable=\"true\"]'))return;if(!settings.clickEffect)settings.clickEffect='sakura';petalBurst(e.clientX,e.clientY)});}
function clickEffectCount(){return ({low:3,medium:6,high:10})[settings.effectAmount]||6}
function petalBurst(x,y){if(!settings.animations)return;const layer=$('#clickEffectLayer');if(!layer)return;const type=settings.clickEffect||'sakura';if(type==='off')return;const symbols={sakura:['✿','❀','✾','🌸'],snow:['❄','❅','✻','❆'],butterfly:['🦋','୨୧'],stars:['✦','✧','★','⋆'],gems:['◆','◇','💎','✧']};if(type==='ripple'){const ring=document.createElement('span');ring.className='click-effect ripple';ring.style.left=`${x}px`;ring.style.top=`${y}px`;layer.append(ring);setTimeout(()=>ring.remove(),950);return}const list=symbols[type]||symbols.sakura;for(let i=0;i<clickEffectCount();i++){const el=document.createElement('span');el.className=`click-effect effect-${type}`;el.textContent=list[Math.floor(Math.random()*list.length)];el.style.left=`${x}px`;el.style.top=`${y}px`;el.style.setProperty('--dx',`${(Math.random()-.5)*(type==='butterfly'?180:130)}px`);el.style.setProperty('--dy',`${-18-Math.random()*(type==='snow'?100:85)}px`);el.style.setProperty('--rot',`${Math.random()*260-130}deg`);el.style.setProperty('--size',`${12+Math.random()*12}px`);layer.append(el);setTimeout(()=>el.remove(),type==='snow'?2100:1450)}while(layer.childElementCount>90)layer.firstElementChild?.remove()}
function startIntro(){
 const intro=$('#intro'),title=$('#titleScreen'),layer=$('#introPetals'),skip=$('#skipIntro');
 const done=()=>{if(introDone)return;introDone=true;if(intro)intro.classList.add('hidden');if(title)title.classList.remove('hidden')};
 if(layer){for(let i=0;i<24;i++){const p=document.createElement('i');p.className='intro-petal';p.style.setProperty('--left',`${Math.random()*100}%`);p.style.setProperty('--delay',`${Math.random()*-7}s`);p.style.setProperty('--duration',`${5+Math.random()*6}s`);p.style.setProperty('--rotate',`${Math.random()*180}deg`);layer.append(p)}}
 if(skip)skip.onclick=done;
 // A hard fallback prevents a missing listener, CSS animation, or browser timer quirk from trapping the player.
 window.setTimeout(done,5000);
 window.setTimeout(()=>{if(!introDone){done();}},8000);
}

function boot(){settings=loadSettings();hydrateSaveFromIndexedDB().then(s=>{const cont=$('#continueGame');if(cont){cont.disabled=!s;cont.style.opacity=cont.disabled?'.6':''}});startIntro();try{setupListeners()}catch(err){console.error('界面初始化异常，已启用开场兜底：',err);toast('部分界面控件初始化失败；开场仍可跳过，请重新载入页面。')}const cont=$('#continueGame');if(cont){cont.disabled=!loadGame();if(!loadGame())cont.style.opacity='.6'}try{if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{})}catch{}setInterval(()=>{if(!state||state.stage!=='playing')return;syncRealClock();if(!state.paused&&settings.autoTime!==false){state.simSecond=(Number(state.simSecond)||0)+1;if(state.simSecond>=60){state.simSecond=0;const speed=Math.max(0.25,Math.min(4,Number(state.speed)||1));advanceSimulationMinutes(speed,'自动时间推进');if(state.settings.randomEvents&&Math.random()<0.0015){maybeNpcInteraction();maybeRandomEvent(false)}processTrainingMilestones();}}updateClock();if(Date.now()-(state.lastSaveAt||0)>15000){state.lastSaveAt=Date.now();saveGame()}},1000);}
boot();